// Archivo: serie.cpp
#include "serie.h"

int tareas_pendientes(int hechas, int total) {
    return total - hechas;
}

std::string estado_serie(int hechas, int total) {
    if (tareas_pendientes(hechas, total) == 0) {
        return "Terminada";
    }
    return "En curso";
}

// Archivo: main.cpp
#include "serie.h"
#include <iostream>

